<script setup lang="ts">
import { useAdminListRoute } from '../navigation'
import { computed, ref, watch } from 'vue'
import type { UserInfo } from '../api'
import { useAdminPage } from '../admin-page'
import { useAdminPaymentConfig } from '../payment-config'
import { getReconciliations, getReconciliation, reconcile, yuan, dateTime, type Reconciliation } from '../growth'
const props = defineProps<{ user: UserInfo }>()
const items = ref<Reconciliation[]>([]), selected = ref<Reconciliation | null>(null), total = ref(0), pageNumber = ref(1), dialog = ref(false)
const day = ref(new Date(Date.now() + 8 * 3600000 - 86400000).toISOString().slice(0, 10))
const maxDate = day.value, minDate = new Date(Date.now() + 8 * 3600000 - 90 * 86400000).toISOString().slice(0, 10)
const labels = { running: '核对中', complete: '已完成', error: '未完成' }
const payment = useAdminPaymentConfig()
const { loading: paymentLoading, error: paymentError } = payment
const online = computed(() => payment.ready('wechat'))
const page = useAdminPage(async valid => { const result = await getReconciliations((pageNumber.value - 1) * 20); if (valid()) { items.value = result.items; total.value = result.total } }, () => { dialog.value = false })
const { error, notice, loading, busy } = page
const routeState = useAdminListRoute('reconciliations', { page: pageNumber }, () => { void page.load() })
watch(pageNumber, page.load)
function run() { if (!online.value || !day.value) return; void page.act(async valid => { try { const result = await reconcile(props.user.id, day.value); if (valid()) { selected.value = result; dialog.value = true; notice.value = '账单核对完成' } } finally { if (valid()) await page.load() } }) }
function inspect(item: Reconciliation) { void page.act(async valid => { const result = await getReconciliation(item.id); if (valid()) { selected.value = result; dialog.value = true } }) }
</script>
<template><section class="admin-section"><p class="text-sm text-muted mb-5">按北京时间核对微信商户支付的收款与退款账单，不包含虚拟支付订单。昨天的账单通常在今天 10:00 后生成，支持最近 90 天。核对只生成差异记录。</p><UAlert v-if="error" :title="error" color="error" class="notice" /><UAlert v-if="notice" :title="notice" color="success" class="notice" /><UAlert v-if="paymentError" :title="'支付配置读取失败：' + paymentError" description="已有对账记录仍可查看，请刷新支付配置后重试下载。" color="warning" class="notice" /><UAlert v-else-if="!paymentLoading && !online" title="配置并启用微信商户支付后可以下载账单核对" color="info" class="notice" /><form class="section-toolbar" @submit.prevent="run"><div class="actions-row"><UInput v-model="day" type="date" :max="maxDate" :min="minDate" aria-label="账单日期" required :disabled="busy" /><UButton label="下载并核对账单" type="submit" :loading="busy" :disabled="busy || loading || !online || !day" /></div><div class="actions-row"><UButton label="刷新支付配置" variant="outline" :loading="paymentLoading" :disabled="busy" @click="payment.load" /><UButton label="刷新记录" variant="outline" :loading="loading" @click="page.load" /></div></form>
  <div class="data-scroll"><table class="data-table"><thead><tr><th>账单日期</th><th>状态</th><th>微信收款</th><th>微信退款</th><th>差异条数</th><th>核对时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{ item.bill_date }}</td><td>{{ labels[item.status] }}</td><td>{{ item.summary.wechat_paid_fen == null ? '—' : yuan(item.summary.wechat_paid_fen) }}</td><td>{{ item.summary.wechat_refunded_fen == null ? '—' : yuan(item.summary.wechat_refunded_fen) }}</td><td>{{ item.summary.differences ?? '—' }}</td><td>{{ dateTime(item.created_at) }}</td><td><UButton label="查看差异" variant="soft" :disabled="busy" @click="inspect(item)" /></td></tr><tr v-if="!items.length"><td colspan="7">{{ loading ? '正在加载' : '暂无账单核对记录' }}</td></tr></tbody></table></div><div class="table-footer"><span>共 {{ total }} 次核对</span><UPagination v-if="total > 20" v-model:page="pageNumber" :total="total" :items-per-page="20" :disabled="loading" /></div>
  <UModal v-model:open="dialog" :title="'账单核对 · ' + (selected?.bill_date || '')" :ui="{ content: 'max-w-5xl' }"><template #body><template v-if="selected"><UAlert v-if="selected.error" :title="selected.error" color="error" /><div v-if="selected.status === 'complete'" class="field-stack"><dl class="info-list"><dt>微信 / 本地收款</dt><dd>{{ yuan(selected.summary.wechat_paid_fen || 0) }} / {{ yuan(selected.summary.local_paid_fen || 0) }}</dd><dt>微信 / 本地退款</dt><dd>{{ yuan(selected.summary.wechat_refunded_fen || 0) }} / {{ yuan(selected.summary.local_refunded_fen || 0) }}</dd><dt>差异</dt><dd>{{ selected.summary.differences }} 条</dd></dl><UAlert v-if="!selected.summary.differences" title="此日收款与退款记录一致" color="success" /><p v-if="(selected.summary.differences || 0) > 5000" class="text-sm text-muted">保存并展示前 5000 条差异，总差异数见上方。</p><div v-if="selected.differences?.length" class="data-scroll"><table class="data-table"><thead><tr><th>订单号 / 退款号</th><th>差异原因</th><th>微信金额</th><th>本地金额</th></tr></thead><tbody><tr v-for="(item, index) in selected.differences" :key="index"><td class="name-cell">{{ item.order_id }}<div class="text-xs text-muted">{{ item.refund_id }}</div></td><td class="comment-cell">{{ item.reason }}</td><td>{{ item.remote_fen === null ? '—' : yuan(item.remote_fen) }}</td><td>{{ item.local_fen === null ? '—' : yuan(item.local_fen) }}</td></tr></tbody></table></div><p class="text-sm text-muted">可复制订单号到会员订单页查询微信最新状态。商户平台发起的未登记退款需人工核对。</p></div><p v-else-if="selected.status === 'running'">账单正在核对，请稍后刷新记录。</p></template></template><template #footer><UButton label="关闭" @click="dialog = false" /></template></UModal>
</section></template>
